  g.fillStyle = C['dial-dim']; g.font = `500 ${Math.round(R * 0.062)}px "JetBrains Mono", monospace`;
  g.fillText('× 1000 tr/min', cx, cy + R * 0.28);
  g.fillStyle = C['dial-ink']; g.font = `700 ${Math.round(R * 0.2)}px "Barlow Condensed", sans-serif`;
  g.fillText(fmt(state.dRpm), cx, cy + R * 0.5);
